const fs = require('fs');
const path = require('path');

// Generate current timestamp
const timestamp = new Date().toISOString();

// The generated file is git-ignored, so a build never dirties a tracked source file.
// It is always (re)written so that it exists before the TypeScript compilation starts.
const outputPath = path.join(__dirname, 'src', 'environments', 'build-info.ts');

const content = `// AUTO-GENERATED by update-build-timestamp.js - do not edit and do not commit.
export const buildTimestamp = '${timestamp}';
`;

fs.mkdirSync(path.dirname(outputPath), { recursive: true });
fs.writeFileSync(outputPath, content);
console.log(`Wrote build timestamp ${timestamp} to src/environments/build-info.ts`);
